create table if not exists public.real_editorial_trawel_media_mappings (
 id uuid primary key default gen_random_uuid(), package_id uuid not null, approval_decision_id uuid not null references public.real_editorial_structured_package_approvals(id), destination_id uuid not null, execution_id uuid not null, local_asset_id uuid not null, checksum_sha256 text not null check (checksum_sha256 ~ '^[a-f0-9]{64}$'), trawel_media_id text null, endpoint_identity text not null, upload_state text not null check (upload_state in ('COMPLETE','FAILED_RETRYABLE','FAILED_PERMANENT')), failure_code text null, failure_message text null, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), uploaded_at timestamptz null, unique(package_id,local_asset_id,checksum_sha256)
);
create table if not exists public.real_editorial_trawel_media_ingress_receipts (
 id uuid primary key default gen_random_uuid(), package_id uuid not null, approval_decision_id uuid not null references public.real_editorial_structured_package_approvals(id), started_at timestamptz not null, completed_at timestamptz null, asset_count integer not null, uploaded_count integer not null, reused_count integer not null, failed_count integer not null, state text not null check (state in ('MEDIA_PENDING','MEDIA_PARTIAL','MEDIA_COMPLETE')), created_at timestamptz not null default now()
);
